//! ⏯️ Original native writer arrays and payload pointers close under unchanged caller authority.
use super::*;
use semio_framework_value::{retirement::controlled::ControlledRetirement,retained_clone::RetainedCloneGrant};
#[test]
fn original_tool_run_writer_preserves_native_members_pointers_and_fixed_grant_closure(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();
 for n in law["counts"].as_array().unwrap(){let n=n.as_u64().unwrap()as usize;let(writer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let identity=ToolRunIdentity::new(ToolRunId{app_instance_id:7,run:11},[17;32]);let mut writer=ToolRunTickWriter::new(identity);writer.append_ops=(0..n).map(|i|vec![i as u8,(i+1)as u8]).collect();writer.append_entities=(0..n as u64).collect();writer.entity_marks=(0..n as u32).collect();writer.payload=Some(vec![b'x';law["payloadBytes"].as_u64().unwrap()as usize]);writer.steps=(0..n).map(|i|ToolRunStep{sequence:i as u64,kind:ToolRunStepKind::Info,stage:2,reason:1,subject:Some(i as u64),repeat:1,args:vec![ToolRunStepArg::Unsigned(i as u64)]}).collect();writer.pages=vec![ToolRunTracePage{identity,page:0,ops:vec![ToolRunTraceOp::Clear]}];writer.page_ops=vec![ToolRunTraceOp::Clear];writer.progress=Some(ToolRunProgress{identity,sequence:0,state:ToolRunState::Running,stage:2,completed:n as u64,total:Some(n as u64),counters:vec![ToolRunCounter{counter:1,value:19}],units_per_second:0.0,conflicts:0,steps:ToolRunStepRing::from_steps(writer.steps.clone()).unwrap()});writer});
  let mut born=heap.requested_bytes;let mut released=heap.released_bytes;let payload_pointer=writer.payload.as_ref().unwrap().as_ptr();let op_pointers:Vec<_>=writer.append_ops.iter().map(Vec::as_ptr).collect();assert_eq!(serde_json::to_value(&writer.append_ops).unwrap(),serde_json::json!((0..n).map(|i|vec![i as u8,(i+1)as u8]).collect::<Vec<_>>()));let mut owner=ControlledRetirement::new(writer).ok().unwrap();let mut turns=0;
  while !owner.terminal_is_empty(){let(demand,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_value::RetirementDemand{copy_bytes:owner.next_copy_byte_demand().unwrap(),capacity_bytes:owner.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut denials=vec![RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}];if demand.copy_bytes>0{denials.push(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant});}if demand.capacity_bytes>0{denials.push(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant});}if demand.release_bytes>0{denials.push(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant});}for denied in denials{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(denied));if let Ok(step)=result{assert_eq!(step.progress(),Default::default(),"original ToolRun n={n} turn={turns} denied={denied:?} demand={demand:?}");}assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if let Some(original)=owner.original(){assert_eq!(original.payload.as_ref().unwrap().as_ptr(),payload_pointer);assert_eq!(original.append_ops.iter().map(Vec::as_ptr).collect::<Vec<_>>(),op_pointers);}
   let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;turns+=1;assert!(turns<100000);
  }assert_eq!(born,released);let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] original ToolRun writer n={n} turns={turns} physical={released} originalMemberPointers same fixed5currencyGrant eachNativeExtent terminalDrop0 independentSerde=true");
 }
}
